window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"8skU84PCfIk","speaker":"Takaichi Sanae","role":"Prime Minister","country":"Japan","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=8skU84PCfIk","date":"20260923","title":"🇯🇵 Japan - Prime Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1292,"words":2880,"counts":{"claims":41,"promises":15,"attacks":0},"topics":[{"topic":"UN reform","share":0.1534,"seconds":198},{"topic":"North Korea","share":0.1044,"seconds":135},{"topic":"Maritime order","share":0.0638,"seconds":82},{"topic":"Indo-Pacific order","share":0.0589,"seconds":76},{"topic":"AI governance","share":0.0578,"seconds":75},{"topic":"Russia-Ukraine war","share":0.056,"seconds":72},{"topic":"Japan climate policy","share":0.0554,"seconds":72},{"topic":"Nuclear disarmament","share":0.0547,"seconds":71},{"topic":"AI summit","share":0.0518,"seconds":67},{"topic":"Middle East tensions","share":0.0516,"seconds":67},{"topic":"Japan ODA Africa","share":0.0508,"seconds":66},{"topic":"Gulf energy resilience","share":0.0507,"seconds":65},{"topic":"International order","share":0.0489,"seconds":63},{"topic":"Disaster risk reduction","share":0.0482,"seconds":62},{"topic":"Africa food crisis","share":0.0469,"seconds":61},{"topic":"UN role","share":0.0468,"seconds":60}],"timeline":[[3,66,"International order"],[68,128,"UN role"],[130,197,"Middle East tensions"],[198,259,"Africa food crisis"],[260,336,"Indo-Pacific order"],[337,403,"Gulf energy resilience"],[403,474,"Nuclear disarmament"],[475,538,"North Korea"],[540,611,"North Korea"],[612,684,"Russia-Ukraine war"],[685,768,"Maritime order"],[768,834,"Japan ODA Africa"],[836,898,"Disaster risk reduction"],[899,971,"Japan climate policy"],[971,1046,"AI governance"],[1047,1114,"AI summit"],[1115,1177,"UN reform"],[1178,1244,"UN reform"],[1245,1315,"UN reform"]],"stances":{"International order":"Takaichi Sanae states that the international order is experiencing great instability and faces difficult challenges due to shifting power balances and geopolitical competition.","UN role":"Takaichi Sanae states that despite global challenges and concerns about the UN's performance, the organization is more important than ever for peace and stability.","Middle East tensions":"Japan is engaging in diplomatic efforts to achieve early deescalation of the situation while highlighting challenges to navigation and supply concerns.","Africa food crisis":"Takaichi Sanae states that disruptions in fertilizer supplies are increasing the risk of a food crisis in Africa and Asia, while noting that geopolitical tensions have recently hampered free trade and supply chains.","Indo-Pacific order":"Takaichi Sanae states that Japan has updated the free and open Indo-Pacific framework and emphasizes three pillars, including strengthening supply chain resilience for energy and critical minerals.","Gulf energy resilience":"Japan is formulating a cooperation plan to strengthen the economic and energy resilience of Gulf countries and proposing a vision for resilient supply chains.","Nuclear disarmament":"Japan asserts its mission to lead international efforts for a world without nuclear weapons based on the experiences of atomic bombings and calls for solidarity in strengthening the NPT regime.","North Korea":"Takaichi Sanae states that North Korea's nuclear and missile programs, along with its cyber activities, violate UN resolutions and threaten international peace, emphasizing the need for complete denuclearization.","Russia-Ukraine war":"Takaichi Sanae states that the UN Security Council is not functioning due to Russia's aggression and veto power, while highlighting Japan's commitment to the rule of law through support for international courts and a new peace mediation unit.","Maritime order":"Japan will play a proactive role in ensuring free and safe navigation in the Strait of Hormuz and Bab el-Mandeb while maintaining maritime order through cooperation with relevant countries and the IMO.","Japan ODA Africa":"Takaichi Sanae states that Japan has provided significant development aid and will continue to promote diplomacy with Africa for mutual prosperity.","Disaster risk reduction":"Japan aims to become the world's leading nation in disaster risk reduction by appointing a new minister and sharing its expertise globally.","Japan climate policy":"Takaichi Sanae states that Japan prioritizes the framework for disaster risk reduction and green transformation to achieve net zero by 2050 while balancing economic growth.","AI governance":"Japan has established international principles for generative AI and is working with partners to create a safe ecosystem while addressing risks from misinformation.","AI summit":"Takaichi Sanae states Japan intends to host an AI summit and emphasizes the necessity of UN reform and multilateral cooperation.","UN reform":"Takaichi Sanae calls for vigorous UN reform, the deletion of enemy state clauses from the UN Charter in accordance with a 2005 resolution, and building on the achievements of Secretary General Antonio Guterres."},"claims":[{"t":46,"quote":"The free and open international order based on the rule of law that we have fostered is facing difficult challenges on multiple Amid a shifting balance of power and intensifying geopolitical competition, innocent civilian lives are being lost around the world every day.","topic":"International order","kind":"fact"},{"t":68,"quote":"The stable postcold war era is now a thing of the past. The distribution of goods is stagnating. People across the world are suffering from high cost of living.","topic":"UN role","kind":"fact"},{"t":80,"quote":"Progress towards development goals is not on track and human rights issues are arising in various places around the world.","topic":"UN role","kind":"fact"},{"t":130,"quote":"This year marks the 70th anniversary of Japan's accession to the United Nations.","topic":"Middle East tensions","kind":"fact"},{"t":169,"quote":"free and safe navigation is increasingly under challenge in the straight of Hormuz which is an international public good.","topic":"Middle East tensions","kind":"fact"},{"t":198,"quote":"Due to ris disruptions in the supply of fertilizers, the risk of food crisis is mounting with Africa and Asia being hit particularly hard.","topic":"Africa food crisis","kind":"fact"},{"t":235,"quote":"exactly 10 years ago, former Prime Minister Abishzo advocated a free and open Indo-Pacific FOIP at the Tokyo International Conference on African Development TikT held in Kenya.","topic":"Africa food crisis","kind":"fact"},{"t":262,"quote":"in May this year, I announced the updated free and open Indo-Pacific FO.","topic":"Indo-Pacific order","kind":"fact"},{"t":319,"quote":"Japan has also launched the partnership on wide energy resources resilience Asia power Asia to strengthen energy and resource supply resilience in Asia","topic":"Indo-Pacific order","kind":"fact"},{"t":338,"quote":"Japan is currently formulating a comprehensive cooperation plan aimed at strengthening the economic and energy resilience of Gulf countries in the Middle East.","topic":"Gulf energy resilience","kind":"fact"},{"t":386,"quote":"One example is the resilient and inclusive supply chain enhancement partnership rise.","topic":"Gulf energy resilience","kind":"fact"},{"t":403,"quote":"In June, we established Rise Plus. Under the World Bank Group, AM pledged a contribution of 20 million US to help develop the infrastructure essential for critical minerals production.","topic":"Nuclear disarmament","kind":"fact"},{"t":424,"quote":"Since the end of the Second World War, Japan has consistently and seriously pursued efforts towards nuclear disarmament","topic":"Nuclear disarmament","kind":"fact"},{"t":487,"quote":"The situations in Ukraine, in North Korea have reminded the world of growing risks and threats posed by nuclear weapons.","topic":"North Korea","kind":"fact"},{"t":495,"quote":"There are also concerns regarding the proliferation of nuclear and missile related technologies through the strengthening of military cooperation between Russia and North Korea.","topic":"North Korea","kind":"fact"},{"t":510,"quote":"The advancement of North Korea's nuclear and missile programs as well as its use of malicious cyber activities including cryptocurrency thefts as source of funding are clear violations of relevant security council resolutions and pose a serious threat to international peace and security.","topic":"North Korea","kind":"fact"},{"t":548,"quote":"The abductees are still denying their freedoms and their families continue to suffer.","topic":"North Korea","kind":"fact"},{"t":561,"quote":"As the abductees and their families are aging, the abductions issue must be resolved immediately.","topic":"North Korea","kind":"fact"},{"t":616,"quote":"a permanent member of the security council which is with a special responsibility for international peace and security has initiated an act of aggression against another country and has vetoed security council resolutions concerning its own actions.","topic":"Russia-Ukraine war","kind":"fact"},{"t":637,"quote":"In this current situation, it must be said that the security council is not functioning for international","topic":"Russia-Ukraine war","kind":"fact"},{"t":658,"quote":"This is demonstrated by Japan's consistent support for and its contrib contributions of judges to various international judicial organizations such as the international court of justice ICJ, the international criminal court ICC and the international tribunal for the law of the sea","topic":"Russia-Ukraine war","kind":"fact"},{"t":679,"quote":"we established a unit for peace mediation within the government of Japan in March of this year.","topic":"Russia-Ukraine war","kind":"fact"},{"t":738,"quote":"Since becoming a member state of the United Nations in 1956, Japan has acted decisively to address global challenges such as eradication of poverty, economic and social development, women's empowerment, climate change, and global","topic":"Maritime order","kind":"fact"},{"t":768,"quote":"To date, Japan has provided ODA totaling over 670 billion US dollars to developing countries and regions and has dispatched almost 60,000 Japan overseas cooperation volunteers to 99 countries.","topic":"Japan ODA Africa","kind":"number"},{"t":789,"quote":"Since 1993, Japan has co-organized the TCAT together with United Nations.","topic":"Japan ODA Africa","kind":"fact"},{"t":853,"quote":"Several large-scale disasters have occurred and continuously caused extreme damage around the world this year, including in Japan.","topic":"Disaster risk reduction","kind":"fact"},{"t":862,"quote":"Natural disasters are becoming more severe and frequent.","topic":"Disaster risk reduction","kind":"fact"},{"t":877,"quote":"I appointed a new minister of state for international disaster risk reduction cooperation.","topic":"Disaster risk reduction","kind":"self_credit"},{"t":883,"quote":"In my cabinet reshuffle last week, I myself in 2015 as minister for internal affairs and communications attended the United Nations World Conference on Disaster Reduction where the SAI framework for disaster risk reduction was adopted.","topic":"Disaster risk reduction","kind":"fact"},{"t":903,"quote":"It is in Sai that Japan will host the Asia-Pacific Ministerial Conference on Disaster Risk Reduction in October next year.","topic":"Japan climate policy","kind":"fact"},{"t":929,"quote":"Japan has been advancing green transformation GS GX efforts with the goal of achieving net zero by 2050.","topic":"Japan climate policy","kind":"fact"},{"t":986,"quote":"Next year, Japan will host the World Horicultural Exposition 2027 in Yokohama, which is an industrial trade fair showcasing green technologies and approaches to sustainable development.","topic":"AI governance","kind":"fact"},{"t":1021,"quote":"Japan took the initiative to launch the Hiroshima AI process, establishing the world's first internal world's first international principles and code of conduct to govern generative AI.","topic":"AI governance","kind":"self_credit"},{"t":1049,"quote":"we intend to host an AI summit in Japan at the earliest opportunity","topic":"AI summit","kind":"fact"},{"t":1054,"quote":"since the end of the Second World War, Japan has built the peace and prosperity it has today through the tireless efforts of our predecessors and the goodwill of a large number of countries","topic":"AI summit","kind":"fact"},{"t":1138,"quote":"the charter of the United Nations, which is now 81 years old","topic":"UN reform","kind":"fact"},{"t":1147,"quote":"A United Nations General Assembly resolution was adopted in 2005 to delete references to enemy states from the charter of the United Nations expressing the resolve of the heads of state and government of all member states.","topic":"UN reform","kind":"fact"},{"t":1170,"quote":"Japan takes pride and honor in its significant contributions to the efforts of the United Nations for the last 70 years.","topic":"UN reform","kind":"self_credit"},{"t":1185,"quote":"The current structure of the security council whose mandate is to maintain international peace and security reflects the international situation as it stood in We need to transform it without delay into a structure that truly reflects the current realities of the international community.","topic":"UN reform","kind":"fact"},{"t":1215,"quote":"A majority of member states support the expansion of both categories.","topic":"UN reform","kind":"number"},{"t":1245,"quote":"we have worked handinhand with United Nations on the two indispensable tasks of establishing rules and institutions and providing support on the ground.","topic":"UN reform","kind":"fact"}],"promises":[{"t":119,"quote":"Japan will continue to fulfill its significant responsibilities towards the United Nations","topic":"UN role","kind":"promise"},{"t":348,"quote":"Through this initiative, we will work to further strengthen the collaboration between the Asia-Pacific region, including Japan and the Gulf countries, to ensure a stable global energy supply.","topic":"Gulf energy resilience","kind":"promise"},{"t":475,"quote":"Japan will persistently advance realistic and practical efforts, including enhancing the transparency of nuclear forces and promoting a deeper understanding of the realities of atomic bombings.","topic":"North Korea","kind":"promise"},{"t":576,"quote":"I am prepared to engage in dialogue and take concrete action to establish a mutually fruitful relationship in accordance with the Japan DPRK Pyongyang declaration.","topic":"North Korea","kind":"promise"},{"t":588,"quote":"Third, Japan will continue to contribute to the maintenance and development of a free and open international order based on the rule of law.","topic":"North Korea","kind":"promise"},{"t":717,"quote":"Japan will continue to work closely with relevant countries and the international maritime organization IMO towards the maintenance of the maritime order in the Middle East.","topic":"Maritime order","kind":"promise"},{"t":818,"quote":"For example, we will promote industrial development, job creation, and enhanced connectivity in Africa.","topic":"Japan ODA Africa","kind":"promise"},{"t":824,"quote":"Furthermore, next year I will host the Pacific Islands leaders meeting Palm in Yokohama, Japan, which Japan has convened together with the Pacific Islands region since 1997.","topic":"Japan ODA Africa","kind":"promise"},{"t":958,"quote":"We will enhance these efforts with a view to strengthening the resilience of the energy supply demand structure and vigorously advance the policy package for wide energy and resources resilience through green transformation or power GX.","topic":"Japan climate policy","kind":"promise"},{"t":971,"quote":"Furthermore, Japan will contribute to global climate action including through GX related efforts such as the Asia zero emission as that simultaneously achieve decarbonization, energy security and economic growth.","topic":"AI governance","kind":"promise"},{"t":1032,"quote":"In parallel, Japan has been working with like-minded partners and global south partners to co-create a safe, secure, and trustworthy AI ecosystem and will enhance cooperation on safety to respond to the risks of highly capable frontier AI.","topic":"AI governance","kind":"promise"},{"t":1049,"quote":"we intend to host an AI summit in Japan at the earliest opportunity","topic":"AI summit","kind":"promise"},{"t":1220,"quote":"Japan is determined to fulfill its solemn responsibility in these UN reforms.","topic":"UN reform","kind":"promise"},{"t":1274,"quote":"Japan will continue to steadily take actions.","topic":"UN reform","kind":"promise"},{"t":1293,"quote":"Japan is determined to create peace and prosperity by making the Indoacific and the international community more resilient and prosperous.","topic":"UN reform","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":"International order","text":"The assembly will hear an address by her Taka Ichi Sanai, Prime Minister of Japan. I request protocol to escort her excellency and invite her to address the assembly. Madame President, excellencies, the international order is experiencing a period of great instability. The free and open international order based on the rule of law that we have fostered is facing difficult challenges on multiple Amid a shifting balance of power and intensifying geopolitical competition, innocent civilian lives are being lost around the world every day."},{"t":68,"topic":"UN role","text":"The stable postcold war era is now a thing of the past. The distribution of goods is stagnating. People across the world are suffering from high cost of living. Progress towards development goals is not on track and human rights issues are arising in various places around the world. Against this backdrop, has the United Nations now 80 years on since its foundation been failing to fulfill its role in promoting peace and stability around the world? We are even hearing such concerns today. Madame President, despite these concerns, the United Nations has never been more important than it is today in bringing about peace and stability to the world and enabling the international community to overcome new challenges and prosper. Japan will continue to fulfill its significant responsibilities towards the United Nations and I am here today to express that resolve."},{"t":130,"topic":"Middle East tensions","text":"This year marks the 70th anniversary of Japan's accession to the United Nations. In this milestone year, I would first like to address how Japan has been tackling the challenges facing the international community working hand in hand with the United Nations. Then together with you all, I would like to take this opportunity to revisit the role of the United Nations in the international community. Madame President, first let us turn our attention to escalating international tensions in the situation in the Middle East has been growing increasingly tense and free and safe navigation is increasingly under challenge in the straight of Hormuz which is an international public good. Japan in cooperation with the international community has been continuing to engage in diplomatic efforts with a view to achieving an early deescalation of the situation across the Middle East. Furthermore, supply concerns regarding fuel, chemical products, and medical supplies are causing significant impact on people's lives and business operations."},{"t":198,"topic":"Africa food crisis","text":"Due to ris disruptions in the supply of fertilizers, the risk of food crisis is mounting with Africa and Asia being hit particularly hard. For many years, we have engaged in dynamic trade in the free and open seas spanning the Pacific Ocean to the Indian Ocean and together we have built a strong and prosperous region. This holds true also in the Atlantic Ocean and Mediterranean Sea. We wish to extend this to Africa as well to turn it into a main artery for growth and prosperity. To that end, exactly 10 years ago, former Prime Minister Abishzo advocated a free and open Indo-Pacific FOIP at the Tokyo International Conference on African Development TikT held in Kenya. However, due to the recent intensification of geopolitical tensions, free trade has been hampered and stable energy supplies and supply chains in general have been disrupted."},{"t":260,"topic":"Indo-Pacific order","text":"Amid this situation, in May this year, I announced the updated free and open Indo-Pacific FO. There I appealed that it is essential for countries to acquire the capabilities to freely determine their own futures and resilience across economic, social and security domains. Japan places particular emphasis on following three pillars that embody this First, Japan is engaged in strengthening the resilience of supply chains for energy and critical minerals. For global energy security, it is crucial to ensure free and transparent energy trade, engage in international coordination on strengthening oil stockpiling and enhance collaboration between producing and consuming countries. Japan has also launched the partnership on wide energy resources resilience Asia power Asia to strengthen energy and resource supply resilience in Asia and has been promoting cooperation in areas such as stockpiling capacity development and credit provision."},{"t":337,"topic":"Gulf energy resilience","text":"Furthermore, Japan is currently formulating a comprehensive cooperation plan aimed at strengthening the economic and energy resilience of Gulf countries in the Middle East. Through this initiative, we will work to further strengthen the collaboration between the Asia-Pacific region, including Japan and the Gulf countries, to ensure a stable global energy supply. Moreover, concerns about arbitrary export restrictions are growing throughout the international community. Japan is proposing a vision for strengthening supply chains which encompasses not only the development of alternative supply chains supply sources but also the enhancement of count's ability to respond to supply disruptions in particular in the field of critical minerals. One example is the resilient and inclusive supply chain enhancement partnership rise. Under this initiative, we are cooperating with countries that produce critical minerals to enable them to play a greater role in mining, refining, and processing."},{"t":403,"topic":"Nuclear disarmament","text":"In June, we established Rise Plus. Under the World Bank Group, AM pledged a contribution of 20 million US to help develop the infrastructure essential for critical minerals production. Second, Japan is devoted to enhancing cooperation towards peace and stability. Since the end of the Second World War, Japan has consistently and seriously pursued efforts towards nuclear disarmament and At the very heart of our aspiration for a world without nuclear weapons lies the earnest plea of the Hibbakia. The catastrophic consequences of nuclear weapons must never be repeated. It is Japan's mission as the only country to have ever suffered atomic bombings during war to lead the efforts of the international community towards a world without nuclear weapons. Japan strongly calls for solidarity within the international community to maintain and strengthen the nuclear non-prololiferation treaty NPT regime to which both nuclear weapon states and non-uclear weapon states are parties."},{"t":475,"topic":"North Korea","text":"Further, Japan will persistently advance realistic and practical efforts, including enhancing the transparency of nuclear forces and promoting a deeper understanding of the realities of atomic bombings. The situations in Ukraine, in North Korea have reminded the world of growing risks and threats posed by nuclear weapons. There are also concerns regarding the proliferation of nuclear and missile related technologies through the strengthening of military cooperation between Russia and North Korea. The security of the Indo-Pacific and Euro Atlantic is inseparable. The advancement of North Korea's nuclear and missile programs as well as its use of malicious cyber activities including cryptocurrency thefts as source of funding are clear violations of relevant security council resolutions and pose a serious threat to international peace and security. The full implementation of Security Council resolutions under the principle of the complete denuclearization of North Korea is essential."},{"t":540,"topic":"North Korea","text":"Moreover, the issue of abductions by North Korea is an ongoing matter with lives at stake. The abductees are still denying their freedoms and their families continue to suffer. This is a matter of grave concern not only for Japan but for the international community. As the abductees and their families are aging, the abductions issue must be resolved immediately. For the sake of the future of both Japan and North Korea, I am prepared to engage in dialogue and take concrete action to establish a mutually fruitful relationship in accordance with the Japan DPRK Pyongyang declaration. Third, Japan will continue to contribute to the maintenance and development of a free and open international order based on the rule of law. Any attempts to unilaterally change the status quo by force or coercion are contrary to the principles enshrined in the charter of the United Nations and must never be tolerated anywhere in the world."},{"t":612,"topic":"Russia-Ukraine war","text":"Russia's aggression against Ukraine is the most obvious example. a permanent member of the security council which is with a special responsibility for international peace and security has initiated an act of aggression against another country and has vetoed security council resolutions concerning its own actions. In this current situation, it must be said that the security council is not functioning for international Since the end of second world war, Japan as a peaceloving nation has attached great importance to the rule of law in the settlement of any disputes. This is demonstrated by Japan's consistent support for and its contrib contributions of judges to various international judicial organizations such as the international court of justice ICJ, the international criminal court ICC and the international tribunal for the law of the sea its we established a unit for peace mediation within the government of Japan in March of this year."},{"t":685,"topic":"Maritime order","text":"Japan will play a more proactive role in the peaceful settlement of disputes. Furthermore, the maritime order based on the rule of law is currently being greatly shaken in the straight of Hormuz. Ensuring free and safe navigation through the state of Hormuse for all vessels without additional costs as has been the case is extremely important not only for the security of the Middle East but also for the stability of the global economy as a whole. Similarly, it is essential to ensure stability in the Bob el Mandde. Japan will continue to work closely with relevant countries and the international maritime organization IMO towards the maintenance of the maritime order in the Middle East. Madame President, next I would like to set out Japan's efforts and commitments towards the United Nations and Since becoming a member state of the United Nations in 1956, Japan has acted decisively to address global challenges such as eradication of poverty, economic and social development, women's empowerment, climate change, and global We have done so our official development assistance and have deepened our solidarity with the global south."},{"t":768,"topic":"Japan ODA Africa","text":"To date, Japan has provided ODA totaling over 670 billion US dollars to developing countries and regions and has dispatched almost 60,000 Japan overseas cooperation volunteers to 99 countries. Additionally, Japan has been promoting initiatives towards achieving universal health coverage UHC across the globe. Since 1993, Japan has co-organized the TCAT together with United Nations. TCAT has served as a platform for reflecting Africa's voice in the sustainable development goals SDGs and for Japan to first put forward the concept of FOYIP. Africa is endowed with a dynamic young population and possesses enormous economic potential. Japan will continue to promote its diplomacy towards Africa so that Japan and Africa can become more resilient and prosperous together. For example, we will promote industrial development, job creation, and enhanced connectivity in Africa. Furthermore, next year I will host the Pacific Islands leaders meeting Palm in Yokohama, Japan, which Japan has convened together with the Pacific Islands region since 1997."},{"t":836,"topic":"Disaster risk reduction","text":"Japan aims to further deepen our collaboration with the Pacific Island count's region and promote the stability and prosperity of the region, including addressing common challenges such as maritime security and climate change. Several large-scale disasters have occurred and continuously caused extreme damage around the world this year, including in Japan. Natural disasters are becoming more severe and frequent. Japan is striving to become the world's leading nation in disaster risk reduction. To share Japan's expertise and technology in disaster risk reduction and contribute to global efforts in this field, I appointed a new minister of state for international disaster risk reduction cooperation. In my cabinet reshuffle last week, I myself in 2015 as minister for internal affairs and communications attended the United Nations World Conference on Disaster Reduction where the SAI framework for disaster risk reduction was adopted."},{"t":899,"topic":"Japan climate policy","text":"Promoting this framework remains one of our top priorities to this day. It is in Sai that Japan will host the Asia-Pacific Ministerial Conference on Disaster Risk Reduction in October next year. To protect the lives of present and future generations, all states must take serious action to tackle global warming. I believe that climate action and economic growth can go hand in hand. Japan has been advancing green transformation GS GX efforts with the goal of achieving net zero by 2050. Uh such capabilities include establishing the basis for the production and engineering of materials such as green steel, utilizing the world's most efficient gas firepower generation, and popularizing the adoption of energy efficient data harnessing Japan's technological capabilities. We will enhance these efforts with a view to strengthening the resilience of the energy supply demand structure and vigorously advance the policy package for wide energy and resources resilience through green transformation or power GX."},{"t":971,"topic":"AI governance","text":"Furthermore, Japan will contribute to global climate action including through GX related efforts such as the Asia zero emission as that simultaneously achieve decarbonization, energy security and economic growth. Next year, Japan will host the World Horicultural Exposition 2027 in Yokohama, which is an industrial trade fair showcasing green technologies and approaches to sustainable development. We sincerely hope that many of you will come to join this expo. There are also challenges arising from technological innovation. Whilst advances in AI bring tremendous opportunities for humanity, they also pose challenges, including those related no related to national security. We also urgently need measures to tackle the spread of information not based on facts as well as the spread of propaganda. Japan took the initiative to launch the Hiroshima AI process, establishing the world's first internal world's first international principles and code of conduct to govern generative AI. In parallel, Japan has been working with like-minded partners and global south partners to co-create a safe, secure, and trustworthy AI ecosystem and will enhance cooperation on safety to respond to the risks of highly capable frontier AI."},{"t":1047,"topic":"AI summit","text":"To accelerate these efforts, we intend to host an AI summit in Japan at the earliest opportunity. Madame President, since the end of the Second World War, Japan has built the peace and prosperity it has today through the tireless efforts of our predecessors and the goodwill of a large number of countries. In the course of these efforts, Japan itself has consistently acted in the spirit of multilateralism towards addressing challenges facing the international community. However, these challenges cannot be cannot be solved by any single country acting alone. Now more than ever, the flag of the United Nations must be held high. And under that banner, member states must mobilize the collective strength of the membership to elaborate new rules and build a framework for cooperation. I am convinced that the United Nations is the only organization capable of taking the helm on a global scale. To this end, as well, reform of the United Nations is essential. The United Nations is a vessel and the responsibility for determining its contents lies with us, namely the member states."},{"t":1115,"topic":"UN reform","text":"Rather than lamenting at the institutional fatigue of the United Nations, member states should unite with one heart, vigorously advance reform of the United Nations and transform the organization into a more resilient and effective United Nations. Let us move forward building on the achievements of the current Secretary General Antonio Gutirez. At the same time, the charter of the United Nations, which is now 81 years old, should also be reviewed regarding the so-called enemy states clauses. A United Nations General Assembly resolution was adopted in 2005 to delete references to enemy states from the charter of the United Nations expressing the resolve of the heads of state and government of all member states. In accordance with this resolution, these clauses must be deleted. I would like to strongly emphasize this position as Japan takes pride and honor in its significant contributions to the efforts of the United Nations for the last 70 years."},{"t":1178,"topic":"UN reform","text":"Furthermore, as a matter of utmost importance, reform of the security council is urgently needed. The current structure of the security council whose mandate is to maintain international peace and security reflects the international situation as it stood in We need to transform it without delay into a structure that truly reflects the current realities of the international community. To this end, it is essential to expand the number of both permanent and non-permanent members in order to ensure the legitimacy and representativeness of the security council. A majority of member states support the expansion of both categories. Japan is determined to fulfill its solemn responsibility in these UN reforms. Madame President, in the 70 years since we became a UN member state, Japan has consistently contributed to the peace and prosperity of the international community as a peaceloving nation under its under its exclusively defenseoriented policy."},{"t":1245,"topic":"UN reform","text":"Furthermore, we have worked handinhand with United Nations on the two indispensable tasks of establishing rules and institutions and providing support on the ground. This policy will remain unchanged in the future. In light of this history, Japan feels to feels a sense of responsibility to safeguard the ideals of the United Nations as our beacon of hope and to carry that light forward into the future. To that end, with its renewed commitment to the United Nations and multilateralism, Japan will continue to steadily take actions. Now at a time when the world is in turmoil, the United Nations itself must be reborn as a more resilient and effective United Nations and regain the trust of the international community. Together with this more resilient and effective United Nations, Japan is determined to create peace and prosperity by making the Indoacific and the international community more resilient and prosperous. Thank you so very much. On behalf of the assembly, I wish to thank the prime minister of Japan."}],"compare":[{"topic":"UN & its reform","share":0.2003,"mean":0.2048,"rank":93,"others":170},{"topic":"Artificial Intelligence","share":0.1097,"mean":0.0502,"rank":32,"others":83},{"topic":"North Korea","share":0.1044,"mean":0.0029,"rank":3,"others":4},{"topic":"Maritime Law","share":0.0638,"mean":0.0015,"rank":2,"others":4},{"topic":"Indo-Pacific","share":0.0589,"mean":0.0038,"rank":6,"others":6},{"topic":"Russia-Ukraine War","share":0.056,"mean":0.0352,"rank":41,"others":44},{"topic":"Nuclear Disarmament","share":0.0547,"mean":0.0038,"rank":10,"others":9},{"topic":"Middle East","share":0.0516,"mean":0.0071,"rank":17,"others":19}]};
